<script setup lang="ts">import{computed,ref}from'vue';import{Head,useForm,usePage}from'@inertiajs/vue3';import InventoryNav from'../../Components/Common/InventoryNav.vue';interface Expense{id:number;number:string;expense_date:string;due_date:string|null;payee:string;category:string;account:string;document_number:string|null;payment_type:string;total:string;paid_amount:string;status:string}interface Account{id:number;code:string;name:string}interface Treasury{id:number;name:string;type:string}const props=defineProps<{expenses:Expense[];expenseAccounts:Account[];treasuryAccounts:Treasury[]}>();const page=usePage<{flash?:{success?:string}}>();const form=useForm({operation_key:crypto.randomUUID(),expense_date:new Date().toISOString().slice(0,10),due_date:'',payee:'',category:'electricity',expense_account_id:'',document_number:'',payment_type:'cash',treasury_account_id:'',subtotal:0,tax:0,paid_amount:0,notes:''});const total=computed(()=>Number(form.subtotal)+Number(form.tax));const sync=()=>{form.paid_amount=form.payment_type==='cash'?Number(total.value.toFixed(2)):0};const save=()=>{sync();form.post('/accounting/expenses',{onSuccess:()=>{form.reset();form.operation_key=crypto.randomUUID()}})};const selected=ref<Expense|null>(null);const pay=useForm({payment_date:new Date().toISOString().slice(0,10),amount:0,treasury_account_id:'',method:'bank_transfer',reference:''});const balance=(e:Expense)=>Number(e.total)-Number(e.paid_amount);const openPay=(e:Expense)=>{selected.value=e;pay.amount=balance(e)};const submitPay=()=>selected.value&&pay.post(`/accounting/expenses/${selected.value.id}/payments`,{onSuccess:()=>{selected.value=null;pay.reset()}});const money=(v:string|number)=>new Intl.NumberFormat('es-HN',{style:'currency',currency:'HNL'}).format(Number(v));</script>
<template><Head title="Gastos y servicios"/><main class="page"><InventoryNav/><p class="eyebrow">CONTABILIDAD</p><h1>Gastos, servicios y alquileres</h1><p>Registra energía, agua, internet, alquiler, combustible, mantenimiento y otros pagos operativos.</p><p v-if="page.props.flash?.success" class="success">{{page.props.flash.success}}</p><form class="card grid" @submit.prevent="save"><h2 class="wide">Nuevo gasto</h2><label>Fecha *<input v-model="form.expense_date" type="date" required></label><label>Vencimiento<input v-model="form.due_date" type="date"></label><label>Pagado a *<input v-model="form.payee" required></label><label>Categoría<select v-model="form.category"><option value="electricity">Energía eléctrica</option><option value="water">Agua</option><option value="internet">Internet</option><option value="telephone">Telefonía</option><option value="rent">Alquiler</option><option value="fuel">Combustible</option><option value="maintenance">Mantenimiento</option><option value="professional">Servicios profesionales</option><option value="tax">Impuestos/tasas</option><option value="other">Otro</option></select></label><label>Cuenta de gasto *<select v-model="form.expense_account_id" required><option value="">Selecciona</option><option v-for="a in expenseAccounts" :key="a.id" :value="a.id">{{a.code}} — {{a.name}}</option></select></label><label>Factura/recibo<input v-model="form.document_number"></label><label>Condición<select v-model="form.payment_type" @change="sync"><option value="cash">Pagado</option><option value="credit">Pendiente</option></select></label><label v-if="form.payment_type==='cash'">Caja o banco *<select v-model="form.treasury_account_id" required><option value="">Selecciona</option><option v-for="a in treasuryAccounts" :key="a.id" :value="a.id">{{a.name}}</option></select></label><label>Subtotal *<input v-model.number="form.subtotal" type="number" min=".01" step=".01" required></label><label>ISV acreditable<input v-model.number="form.tax" type="number" min="0" step=".01"></label><label class="wide">Notas<textarea v-model="form.notes"/></label><div class="wide footer"><strong>Total: {{money(total)}}</strong><span class="error">{{Object.values(form.errors)[0]}}</span><button :disabled="form.processing">Registrar gasto</button></div></form><section class="card table"><table><thead><tr><th>Gasto</th><th>Fecha</th><th>Beneficiario</th><th>Categoría</th><th>Documento</th><th class="right">Total</th><th class="right">Saldo</th><th></th></tr></thead><tbody><tr v-for="e in expenses" :key="e.id"><td>{{e.number}}</td><td>{{e.expense_date}}</td><td>{{e.payee}}</td><td>{{e.account}}</td><td>{{e.document_number||'—'}}</td><td class="right">{{money(e.total)}}</td><td class="right">{{money(balance(e))}}</td><td><button v-if="balance(e)>0" class="link" @click="openPay(e)">Pagar</button></td></tr><tr v-if="!expenses.length"><td colspan="8">No hay gastos registrados.</td></tr></tbody></table></section><div v-if="selected" class="overlay" @click.self="selected=null"><form class="modal" @submit.prevent="submitPay"><h2>Pagar {{selected.number}}</h2><label>Fecha<input v-model="pay.payment_date" type="date" required></label><label>Monto<input v-model.number="pay.amount" type="number" min=".01" :max="balance(selected)" step=".01" required></label><label>Cuenta<select v-model="pay.treasury_account_id" required><option value="">Selecciona</option><option v-for="a in treasuryAccounts" :key="a.id" :value="a.id">{{a.name}}</option></select></label><label>Referencia<input v-model="pay.reference"></label><p class="error">{{Object.values(pay.errors)[0]}}</p><div class="footer"><button type="button" class="secondary" @click="selected=null">Cancelar</button><button>Confirmar pago</button></div></form></div></main></template>
<style scoped>.page{max-width:1500px;margin:auto;padding:2rem}.eyebrow{color:var(--p-primary-color);font-weight:800;font-size:.75rem;letter-spacing:.15em}.card{padding:1.5rem;border:1px solid var(--p-content-border-color);border-radius:1rem;background:var(--p-content-background);margin-top:1rem}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1rem}.wide{grid-column:1/-1}label{display:grid;gap:.35rem;font-weight:600}input,select,textarea{padding:.7rem;border:1px solid var(--p-content-border-color);border-radius:.5rem;background:transparent;color:inherit}textarea{min-height:5rem}.footer{display:flex;justify-content:flex-end;align-items:center;gap:1rem}button{padding:.7rem 1rem;border:0;border-radius:.55rem;background:var(--p-primary-color);color:var(--p-primary-contrast-color);font-weight:700}.secondary,.link{background:transparent;color:var(--p-primary-color);border:1px solid var(--p-content-border-color)}.table{overflow:auto}table{width:100%;border-collapse:collapse}td,th{padding:.8rem;border-bottom:1px solid var(--p-content-border-color);text-align:left;white-space:nowrap}.right{text-align:right}.success{padding:.75rem;background:#dcfce7;color:#166534;border-radius:.5rem}.error{color:#dc2626}.overlay{position:fixed;inset:0;background:#0008;display:grid;place-items:center;padding:1rem;z-index:50}.modal{width:min(32rem,100%);padding:1.5rem;border-radius:1rem;background:var(--p-content-background);display:grid;gap:1rem}.modal label{display:grid}.modal .footer{margin-top:.5rem}@media(max-width:900px){.grid{grid-template-columns:1fr}.wide{grid-column:auto}.page{padding:1rem}}</style>
